use git_zero::{
    Error, ObjectHasher, ObjectId, ObjectInfo, ObjectKind, Repository, Result,
    io::{SliceWriter, Write},
};

/// A complete snapshot whose blob is generated by offset. None of its objects
/// exposes a borrowed-body fast path, exercising streaming for every kind.
pub struct GeneratedRepository {
    size: u64,
    max_read: usize,
    ids: [ObjectId; 3],
    tree: [u8; 128],
    tree_length: usize,
    commit: [u8; 256],
    commit_length: usize,
}

pub fn byte_at(offset: u64) -> u8 {
    (offset % 251) as u8
}

impl GeneratedRepository {
    pub fn new(size: u64, max_read: usize) -> Self {
        assert!(max_read > 0);
        let mut repository = Self {
            size,
            max_read,
            ids: [ObjectId([0; 20]); 3],
            tree: [0; 128],
            tree_length: 0,
            commit: [0; 256],
            commit_length: 0,
        };
        let mut scratch = [0; 1024];
        repository.ids[2] = ObjectHasher::new(&repository, 2)
            .unwrap()
            .finish(&mut scratch)
            .unwrap();
        let mut tree = SliceWriter::new(&mut repository.tree);
        tree.write_all(b"100644 generated.bin\0").unwrap();
        tree.write_all(&repository.ids[2].0).unwrap();
        repository.tree_length = tree.len();
        repository.ids[1] = ObjectHasher::new(&repository, 1)
            .unwrap()
            .finish(&mut scratch)
            .unwrap();
        let mut commit = SliceWriter::new(&mut repository.commit);
        commit.write_all(b"tree ").unwrap();
        commit.write_all(&repository.ids[1].to_hex()).unwrap();
        commit.write_all(b"\nauthor git-zero <git-zero@example.invalid> 0 +0000\ncommitter git-zero <git-zero@example.invalid> 0 +0000\n\nIn-memory snapshot\n").unwrap();
        repository.commit_length = commit.len();
        repository.ids[0] = ObjectHasher::new(&repository, 0)
            .unwrap()
            .finish(&mut scratch)
            .unwrap();
        repository
    }
}

impl Repository for GeneratedRepository {
    fn head(&self) -> ObjectId {
        self.ids[0]
    }

    fn object_count(&self) -> usize {
        self.ids.len()
    }

    fn object_id(&self, index: usize) -> Option<ObjectId> {
        self.ids.get(index).copied()
    }

    fn object_info(&self, index: usize) -> Result<ObjectInfo> {
        let (kind, size) = match index {
            0 => (ObjectKind::Commit, self.commit_length as u64),
            1 => (ObjectKind::Tree, self.tree_length as u64),
            2 => (ObjectKind::Blob, self.size),
            _ => return Err(Error::ObjectNotFound),
        };
        Ok(ObjectInfo { kind, size })
    }

    fn read_object(&self, index: usize, offset: u64, storage: &mut [u8]) -> Result<usize> {
        let info = self.object_info(index)?;
        let length = info
            .size
            .saturating_sub(offset)
            .min(storage.len().min(self.max_read) as u64) as usize;
        if length == 0 {
            return Ok(0);
        }
        match index {
            0 => storage[..length]
                .copy_from_slice(&self.commit[offset as usize..offset as usize + length]),
            1 => storage[..length]
                .copy_from_slice(&self.tree[offset as usize..offset as usize + length]),
            2 => {
                for (index, byte) in storage[..length].iter_mut().enumerate() {
                    *byte = byte_at(offset + index as u64);
                }
            }
            _ => unreachable!(),
        }
        Ok(length)
    }
}
